stage_a_raw:
{
  "decisions": [
    {
      "decision": "flow_variable_domain",
      "evidence": "\"Demand of Each Retail Store (in units)\" / \"Supply Capacity of Each Distribution Center (in units)\"",
      "options": [
        "NonNegativeReals",
        "NonNegativeIntegers"
      ],
      "plausibility": [
        0.7,
        0.3
      ],
      "majority_option": "NonNegativeReals"
    },
    {
      "decision": "demand_constraint_direction",
      "evidence": "\"ensure that each retail store's demand is met\" / \"fully satisfy the demands of all five retail stores\"",
      "options": [
        "sum_i x[i,j] >= demand[j]",
        "sum_i x[i,j] == demand[j]"
      ],
      "plausibility": [
        0.6,
        0.4
      ],
      "majority_option": "sum_i x[i,j] >= demand[j]"
    },
    {
      "decision": "capacity_link_form",
      "evidence": "\"Supply Capacity of Each Distribution Center\" / \"selecting from eight potential distribution centers\"",
      "options": [
        "sum_j x[i,j] <= capacity[i] * y[i]",
        "sum_j x[i,j] <= capacity[i] and x[i,j] <= capacity[i]*y[i]"
      ],
      "plausibility": [
        0.85,
        0.15
      ],
      "majority_option": "sum_j x[i,j] <= capacity[i] * y[i]"
    },
    {
      "decision": "objective_units_scale",
      "evidence": "\"Opening Costs for Each Distribution Center (in dollars)\" / \"Transportation Cost Per Unit ... (in dollars)\"",
      "options": [
        "total cost in dollars (opening + per-unit transport * units)",
        "total cost in thousands of dollars"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "total cost in dollars (opening + per-unit transport * units)"
    },
    {
      "decision": "opening_variable_domain",
      "evidence": "\"selecting from eight potential distribution centers\" / \"select the right combination of distribution centers to open\"",
      "options": [
        "Binary",
        "NonNegativeReals in [0,1]"
      ],
      "plausibility": [
        0.97,
        0.03
      ],
      "majority_option": "Binary"
    },
    {
      "decision": "objective_sense",
      "evidence": "\"minimizing costs\" / \"lowest possible total cost\"",
      "options": [
        "minimize opening + transportation cost",
        "maximize opening + transportation cost"
      ],
      "plausibility": [
        0.99,
        0.01
      ],
      "majority_option": "minimize opening + transportation cost"
    }
  ]
}
